+      return (
+        content.slice(0, afterFrontmatter) +
+        "\n\n" +
+        sourceNote +
+        content.slice(afterFrontmatter).trimStart()
+      );
+    }
+  }
+
+  // Add frontmatter and source note
+  return generateFrontmatter(packageName) + sourceNote + content;
